        self.name = os.path.basename(path)
        self.path = path

        if os.path.isdir(self.path):
            self.type = DIR_MIME_TYPE
            self.size = None
            self.time = None
        else:
            try:
                stat = os.stat(self.path)
                self.size = stat.st_size
                self.time = stat.st_mtime
            except OSError:
                self.size = None
                self.time = None

            if has_magic:
                mime = magic.Magic(mime=True)
                # Python2 magic.files rejects non-ascii filenames, magic.isfile
                # errors out if the file is a symlink; so fscking use magic.from_file
                # which shouldn't readline() the file(1) from /dev/null
                self.type = mime.from_file(self.path)

                # files with no mime type are executables - unless
                # they're symlinks, then they're links
                if not self.type:
                    self.type = (LINK_MIME_TYPE if os.path.islink(self.path) else EXEC_MIME_TYPE)
                # sometimes 'C' is returned!
                if self.type == 'x-empty' or self.type == 'C':
                    self.type = None


            else:
                mime = mimetypes.MimeTypes()
                _, m = mime.guess_type(unquote(self.path))
                self.type = m or EXEC_MIME_TYPE

    @staticmethod
    def get_objects(path):
        objects = []

        if path:
            for name in os.listdir(path):
                object_path = os.path.join(path, name)
                objects.append(Object(object_path))

        return objects

