from common.application import Application
from keystonemiddleware.auth_token import filter_factory as auth_filter_factory

class KeystoneApplication(Application):

    """
    An Application which uses Keystone for authorisation using RBAC
    """

    def __init__(self, configuration):
        super(KeystoneApplication, self).__init__(configuration)
        try:
            self.required_role = self.config.get('authorisation', 'required_role')
        except NoSectionError:
            raise ValueError("No authorisation section found")
        except NoOptionError:
            raise ValueError("No required role specified")

    def _check_auth(self, req):
        if 'HTTP_X_ROLES' in req.environ:
            user_roles = req.environ['HTTP_X_ROLES'].split(',')
            return self.required_role in user_roles
        return False

def keystone_auth_filter_factory(global_config, **local_config):
    global_config.update(local_config)
    config_file_name = global_config.get('config_file')
    if not config_file_name:
        raise ValueError("Keystone config_file not specified")
    config_file = ConfigParser.SafeConfigParser()
    no_of_files_read = config_file.read(config_file_name)
    if not no_files_read:
        raise ValueError("Keystone config_file %s is unreadable",
            config_file_name)
    try:
        global_config.update(config_file.items('keystone_authtoken'))
    except NoSectionError:
        raise ValueError("No keystone_authtoken section found in %s",
            config_file_name)
    return auth_filter_factory(global_config)

import ConfigParser
from common.application import Application
from keystonemiddleware.auth_token import filter_factory as auth_filter_factory

class KeystoneApplication(Application):

    """
    An Application which uses Keystone for authorisation using RBAC
    """

    def __init__(self, configuration):
        super(KeystoneApplication, self).__init__(configuration)
        self.required_role = self.config.get('authorisation', 'required_role')
        if self.required_role is None:
            raise ValueError("No required role supplied")

    def _check_auth(self, req):
        if 'HTTP_X_ROLES' in req.environ:
            user_roles = req.environ['HTTP_X_ROLES'].split(',')
            return self.required_role in user_roles
        return False

def keystone_auth_filter_factory(global_config, **local_config):
    global_config.update(local_config)
    config_file_name = global_config.get('config_file')
    if not config_file_name:
        raise ValueError("No config file provided")
    config_file = ConfigParser.SafeConfigParser()
    try:
        config_file.read(config_file_name)
    except ConfigParser.Error:
        raise ValueError("Config file could not be parsed")
    try:
        keystone_options = config_file.items('keystone_authtoken')
    except ConfigParser.NoSectionError:
        raise ValueError("Keystone config section not found in config file")
    global_config.update(keystone_options)
    return auth_filter_factory(global_config)

